/**
 * Which models have their PROVIDER'S OWN computer tool, from LiteLLM's model
 * catalog (`supports_computer_use`). models.dev has no such field.
 *
 * Only the flagged ids are kept (a few dozen after normalising), never the
 * 3 MB catalog. The order of trust: a fresh cache (refreshed daily), then the
 * snapshot shipped in the build (`computer-use-models.json`, regenerated by
 * `scripts/fetch-computer-use-models.mjs`). Sync reads, so the toolset gate can
 * ask without awaiting; a stale cache refreshes in the background.
 */

import fs from "node:fs";
import path from "node:path";
import { getUserDataPath } from "@/paths/paths";
import snapshot from "./computer-use-models.json";

export const LITELLM_CATALOG_URL =
  "https://raw.githubusercontent.com/BerriAI/litellm/main/model_prices_and_context_window.json";
const REFRESH_MS = 24 * 60 * 60 * 1000;
const FETCH_TIMEOUT_MS = 30_000;

/**
 * One spelling for a model however a catalog or a provider writes it:
 * `bedrock_converse/us.anthropic.claude-haiku-4-5-20251001-v1:0`,
 * `vertex_ai/claude-opus-4-8@default` and `claude-haiku-4.5` all name the
 * catalog's `claude-haiku-4-5`.
 */
export function normaliseModelId(id: string): string {
  return id
    .trim()
    .toLowerCase()
    .split("/")
    .pop()!
    .replace(/@.*$/, "")
    .replace(/^(?:[a-z]{2,6}(?:-[a-z]{2,6})?\.)?anthropic\./, "")
    .replace(/-v\d+(?::\d+)?$/, "")
    .replace(/-\d{8}$/, "")
    .replace(/-\d{4}-\d{2}-\d{2}$/, "")
    .replace(/\./g, "-");
}

/** The flagged ids of a raw LiteLLM catalog, normalised and sorted. */
export function flaggedIds(catalog: Record<string, unknown>): string[] {
  const out = new Set<string>();
  for (const [key, row] of Object.entries(catalog)) {
    if (row && typeof row === "object" && (row as { supports_computer_use?: unknown }).supports_computer_use === true) {
      out.add(normaliseModelId(key));
    }
  }
  return [...out].sort();
}

type Cache = { fetchedAt: number; ids: string[] };

let ids: Set<string> | null = null;
let refreshing = false;

function cachePath(): string {
  return path.join(getUserDataPath(), "cache", "computer-use-models.json");
}

function readCache(): Cache | null {
  try {
    const c = JSON.parse(fs.readFileSync(cachePath(), "utf-8")) as Cache;
    return Array.isArray(c.ids) && c.ids.length > 0 ? c : null;
  } catch {
    return null;
  }
}

async function refresh(): Promise<void> {
  if (refreshing) return;
  refreshing = true;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
  try {
    const res = await fetch(LITELLM_CATALOG_URL, {
      headers: { "User-Agent": "Atlarix/1.0" },
      signal: controller.signal,
    });
    if (!res.ok) return;
    const fresh = flaggedIds((await res.json()) as Record<string, unknown>);
    // An empty list is a broken catalog, not "no model can do it".
    if (fresh.length === 0) return;
    const file = cachePath();
    const tmp = `${file}.${process.pid}.tmp`;
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(tmp, JSON.stringify({ fetchedAt: Date.now(), ids: fresh } satisfies Cache));
    fs.renameSync(tmp, file);
    ids = new Set(fresh);
  } catch {
    // Offline or the catalog moved: the cache or snapshot keeps answering.
  } finally {
    clearTimeout(timer);
    refreshing = false;
  }
}

function load(): Set<string> {
  if (ids) return ids;
  const cache = readCache();
  ids = new Set(cache?.ids ?? (snapshot as { ids: string[] }).ids);
  if (!cache || Date.now() - cache.fetchedAt > REFRESH_MS) void refresh();
  return ids;
}

/** Does this model's provider offer its own computer tool for it? */
export function hasNativeComputerTool(modelId: string | undefined): boolean {
  if (!modelId) return false;
  return load().has(normaliseModelId(modelId));
}

export function __setCatalogIdsForTests(list: string[] | null): void {
  ids = list ? new Set(list.map(normaliseModelId)) : null;
}
